async sortBy(sortColumn, sortDirection, _resort = false) {
  if (!(sortColumn in columns)) {
    sortColumn = "date";
  }
  if (!["ascending", "descending"].includes(sortDirection)) {
    sortDirection = "descending";
  }
  this.sortColumn = sortColumn;
  this.sortDirection = sortDirection;
  this._sortComparator = comparators[sortColumn];
  this._liveView.sortColumn = columns[sortColumn];
  this._liveView.sortDescending = sortDirection == "descending";

  this._rowMap.length = 0;
  this._rowMap.length = await this._liveView.countMessages();
  await this._liveView.selectMessages();
}

NS_IMETHODIMP LiveView::GetSortColumn(nsILiveView::SortColumn* aSortColumn) {
  *aSortColumn = mSortColumn;
  return NS_OK;
}

NS_IMETHODIMP LiveView::SetSortColumn(nsILiveView::SortColumn aSortColumn) {
  mSortColumn = aSortColumn;
  ResetStatements();
  return NS_OK;
}

NS_IMETHODIMP LiveView::GetSortDescending(bool* aSortDescending) {
  *aSortDescending = mSortDescending;
  return NS_OK;
}

NS_IMETHODIMP LiveView::SetSortDescending(bool aSortDescending) {
  mSortDescending = aSortDescending;
  ResetStatements();
  return NS_OK;
}

void LiveView::ResetStatements() {
  if (mCountStmt) {
    mCountStmt->Finalize();
    mCountStmt = nullptr;
  }
  if (mCountUnreadStmt) {
    mCountUnreadStmt->Finalize();
    mCountUnreadStmt = nullptr;
  }
  if (mSelectStmt) {
    mSelectStmt->Finalize();
    mSelectStmt = nullptr;
  }
  if (mSelectGroupStmt) {
    mSelectGroupStmt->Finalize();
    mSelectGroupStmt = nullptr;
  }
